    'analysis_initial_stage_2_title': { 'English': 'Looking for non-data rows', 'Mandarin': '正在查找非数据行', 'Japanese': 'データ以外の行を確認中', 'Malay': 'Mencari baris bukan data' },
    'analysis_initial_stage_2_desc': { 'English': 'Spotting title rows, totals and blank lines that are not real data.', 'Mandarin': '找出标题行、合计行和空行等非数据内容。', 'Japanese': 'タイトル行、合計行、空行など実データでない行を探しています。', 'Malay': 'Mengesan baris tajuk, jumlah dan baris kosong yang bukan data sebenar.' },
    'analysis_initial_stage_3_title': { 'English': 'Planning safe preparation', 'Mandarin': '正在规划安全的数据准备', 'Japanese': '安全なデータ準備を計画中', 'Malay': 'Merancang penyediaan selamat' },
    'analysis_initial_stage_3_desc': { 'English': 'Deciding what, if anything, needs tidying. Nothing is changed yet.', 'Mandarin': '判断是否需要整理、整理什么。目前还没有改动任何内容。', 'Japanese': '整える必要があるか判断しています。まだ何も変更していません。', 'Malay': 'Menentukan apa yang perlu dikemas, jika ada. Belum ada yang diubah.' },
    'analysis_initial_stage_4_title': { 'English': 'Preparing a clean analysis view', 'Mandarin': '正在准备干净的分析视图', 'Japanese': '整理済みの分析ビューを準備中', 'Malay': 'Menyediakan paparan analisis yang bersih' },
    'analysis_initial_stage_4_desc': { 'English': 'Applying reversible tidy-ups to a working copy. Your original file is never modified.', 'Mandarin': '只在工作副本上做可撤销的整理。你的原始文件不会被修改。', 'Japanese': '作業用コピーに取り消し可能な整形のみ適用します。元のファイルは変更されません。', 'Malay': 'Menggunakan pengemasan boleh batal pada salinan kerja. Fail asal anda tidak diubah.' },
    'analysis_initial_stage_5_title': { 'English': 'Checking data quality', 'Mandarin': '正在检查数据质量', 'Japanese': 'データ品質を確認中', 'Malay': 'Menyemak kualiti data' },
    'analysis_initial_stage_5_desc': { 'English': 'Making sure numbers and dates can be analysed reliably.', 'Mandarin': '确认数字和日期可以被可靠地分析。', 'Japanese': '数値と日付を確実に分析できるか確認しています。', 'Malay': 'Memastikan nombor dan tarikh boleh dianalisis dengan dipercayai.' },
    'analysis_initial_stage_6_title': { 'English': 'Connecting the query engine', 'Mandarin': '正在连接查询引擎', 'Japanese': 'クエリエンジンに接続中', 'Malay': 'Menyambung enjin pertanyaan' },
    'analysis_initial_stage_6_desc': { 'English': 'Getting the full dataset ready for fast questions.', 'Mandarin': '让完整数据可以被快速查询。', 'Japanese': '全データをすばやく照会できるよう準備しています。', 'Malay': 'Menyediakan set data penuh untuk pertanyaan pantas.' },
    'analysis_initial_stage_7_title': { 'English': 'Choosing what to investigate', 'Mandarin': '正在确定分析方向', 'Japanese': '調査する内容を選定中', 'Malay': 'Memilih perkara untuk disiasat' },
    'analysis_initial_stage_7_desc': { 'English': 'Drafting the questions worth answering from your data.', 'Mandarin': '拟出值得从数据中回答的问题。', 'Japanese': 'データから答える価値のある問いを作成しています。', 'Malay': 'Menyediakan soalan yang berbaloi dijawab daripada data anda.' },
    'analysis_initial_stage_8_title': { 'English': 'Running the analysis', 'Mandarin': '正在运行分析', 'Japanese': '分析を実行中', 'Malay': 'Menjalankan analisis' },
